<script setup lang="ts">
import { ArrowLeft, CheckCircle2, CreditCard, KeyRound, Save, ShieldCheck } from '@lucide/vue'
import { onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import api from '../api'
import BrandLogo from '../components/BrandLogo.vue'

const router=useRouter();const plans=ref<any[]>([]);const loading=ref(true);const saving=ref<number|null>(null);const message=ref('');const error=ref('');const paymob=reactive({secret_key:'',public_key:'',hmac_secret:'',iframe_id:'',payment_methods:'',api_base:'https://accept.paymob.com',checkout_base:'https://accept.paymob.com/unifiedcheckout'});const paymobSaving=ref(false)
async function load(){loading.value=true;try{const [planResponse,paymobResponse]=await Promise.all([api.get('/platform/plans'),api.get('/platform/paymob-settings')]);plans.value=planResponse.data.plans;Object.assign(paymob,{payment_methods:paymobResponse.data.payment_methods.join(',')||'',iframe_id:paymobResponse.data.iframe_id||'',api_base:paymobResponse.data.api_base,checkout_base:paymobResponse.data.checkout_base})}finally{loading.value=false}}
async function savePlan(plan:any){saving.value=plan.id;message.value='';error.value='';try{await api.patch(`/platform/plans/${plan.id}`,{...plan,features:typeof plan.features==='string'?plan.features.split('\n').map((item:string)=>item.trim()).filter(Boolean):plan.features});message.value=`${plan.name} updated.`}catch(e:any){error.value=e.response?.data?.message||'Unable to save plan.'}finally{saving.value=null}}
async function savePaymob(){paymobSaving.value=true;message.value='';error.value='';try{await api.put('/platform/paymob-settings',{...paymob,payment_methods:paymob.payment_methods.split(',').map((item:string)=>Number(item.trim())).filter(Boolean)});message.value='Paymob settings saved securely.'}catch(e:any){error.value=e.response?.data?.message||'Unable to save Paymob settings.'}finally{paymobSaving.value=false}}
function setFeatures(plan:any,event:Event){plan.features=String((event.target as HTMLTextAreaElement).value).split('\n')}
onMounted(load)
</script>
<template><div class="platform-settings-page"><header><BrandLogo/><button class="button secondary" @click="router.push('/admin/settings')"><ArrowLeft/>Back to platform settings</button></header><main><div class="settings-hero"><div><span>PLATFORM COMMERCIAL CONTROL</span><h1>Plans & payments</h1><p>Configure what each AcademyHub plan includes and connect Paymob without exposing gateway secrets in the browser.</p></div><ShieldCheck/></div><div v-if="loading" class="loading-state"><span></span>Loading commercial settings…</div><template v-else><div v-if="message" class="settings-message"><CheckCircle2/>{{message}}</div><div v-if="error" class="form-error">{{error}}</div><section class="plan-editor-grid"><article v-for="plan in plans" :key="plan.id" class="plan-editor"><div class="plan-editor-head"><div><span>PLAN {{plan.position}}</span><h2>{{plan.name}}</h2></div><em :class="plan.is_active?'active':'pending'">{{plan.is_active?'Active':'Hidden'}}</em></div><label>Name<input v-model="plan.name"></label><label>Description<textarea v-model="plan.description" rows="2"></textarea></label><div class="plan-fields"><label>Monthly EGP<input v-model.number="plan.monthly_price_minor" type="number" min="0"></label><label>Yearly EGP<input v-model.number="plan.yearly_price_minor" type="number" min="0"></label><label>Centres<input v-model.number="plan.centre_limit" type="number" min="1"></label><label>Students<input v-model.number="plan.student_limit" type="number" min="1"></label><label>Staff<input v-model.number="plan.staff_limit" type="number" min="1"></label><label>Groups<input v-model.number="plan.group_limit" type="number" min="1"></label></div><label>Features <small>one per line</small><textarea :value="(plan.features||[]).join('\n')" @input="plan.features=($event.target as HTMLTextAreaElement).value.split('\n')" rows="4"></textarea></label><div class="plan-actions"><label class="check-label"><input v-model="plan.is_active" type="checkbox"> Active</label><label class="check-label"><input v-model="plan.is_featured" type="checkbox"> Featured</label><button class="button primary" :disabled="saving===plan.id" @click="savePlan(plan)"><Save/> {{saving===plan.id?'Saving…':'Save plan'}}</button></div></article></section><section class="paymob-editor"><div class="settings-card-head"><span><CreditCard/></span><div><small>PAYMOB GATEWAY</small><h2>Egyptian checkout connection</h2><p>Values are encrypted at rest. Leave a credential blank to keep the saved value.</p></div></div><div class="paymob-fields"><label>Secret key<input v-model="paymob.secret_key" type="password" autocomplete="new-password"></label><label>Public key<input v-model="paymob.public_key" type="password" autocomplete="new-password"></label><label>HMAC secret<input v-model="paymob.hmac_secret" type="password" autocomplete="new-password"></label><label>Iframe ID <input v-model="paymob.iframe_id"></label><label>Payment method IDs <input v-model="paymob.payment_methods" placeholder="123456, 789012"></label><label>API base<input v-model="paymob.api_base"></label><label>Checkout base<input v-model="paymob.checkout_base"></label></div><button class="button primary" :disabled="paymobSaving" @click="savePaymob"><KeyRound/> {{paymobSaving?'Saving…':'Save Paymob settings'}}</button></section></template></main></div></template>
